-- Recurring payments (§5.8): generating due payments, atomic saves, price
-- changes, detection dismissals and the hourly job.
--
-- Payments are generated by the app (src/lib/data/recurring.ts, generateDue)
-- from each rule's schedule and price history in src/lib/calc, then inserted
-- with `on conflict (user_id, recurring_rule_id, date) do nothing`, so a
-- payment is never added twice. recurring_rules.generated_through records the
-- last day generated, so a payment the user deleted is not added again.
--
-- The RPCs here are security invoker (RLS applies to every statement), with an
-- empty search_path, callable only by signed-in users:
--   save_expense           an expense with a new category and/or Repeat, in one go
--   create_recurring_rule  a rule, its first price, and links to past payments
--   apply_recurring_price  a price change plus the amounts it moves, together
--
-- Errors: 42501 not signed in; 22023 malformed input; P0002 the expense or
-- rule is not the caller's (or gone); PT409 a payment changed meanwhile (or
-- is already linked to a rule); 23505 a taken category name; 23503 a
-- category or fund that is not the caller's.

-- transactions: a plain unique key, so `on conflict (user_id, recurring_rule_id, date)`
-- can name it (from PostgREST too). NULLs stay distinct, so manual expenses
-- (no rule) are unaffected, exactly as with the 0001 partial index.
drop index public.transactions_recurring_rule_date_key;
alter table public.transactions
  add constraint transactions_user_rule_date_key unique (user_id, recurring_rule_id, date);

-- recurring_rules: how far payments have been generated, and a bound on skips.
alter table public.recurring_rules
  add column generated_through date,
  add constraint recurring_rules_generated_through_check
    check (generated_through is null or generated_through >= anchor_date),
  add constraint recurring_rules_skipped_dates_check check (cardinality(skipped_dates) <= 100),
  add constraint recurring_rules_end_date_check check (end_date is null or end_date >= anchor_date);

-- recurring_dismissals: payment names the user said are not recurring ("No").
create table public.recurring_dismissals (
  user_id uuid not null default auth.uid() references auth.users (id) on delete cascade,
  name_key text not null check (char_length(name_key) between 1 and 100),
  primary key (user_id, name_key)
);

alter table public.recurring_dismissals enable row level security;
revoke all on public.recurring_dismissals from anon, authenticated;
grant select, insert, update, delete on public.recurring_dismissals to authenticated;

create policy "recurring_dismissals: owner select" on public.recurring_dismissals for select to authenticated
  using ((select auth.uid()) = user_id);
create policy "recurring_dismissals: owner insert" on public.recurring_dismissals for insert to authenticated
  with check ((select auth.uid()) = user_id);
create policy "recurring_dismissals: owner update" on public.recurring_dismissals for update to authenticated
  using ((select auth.uid()) = user_id)
  with check ((select auth.uid()) = user_id);
create policy "recurring_dismissals: owner delete" on public.recurring_dismissals for delete to authenticated
  using ((select auth.uid()) = user_id);

-- save_expense ---------------------------------------------------------------
-- Creates (p_id null) or updates an expense. With p_new_category_name it first
-- creates that category (no allocation); with p_repeat (new expenses only) it
-- creates a rule from the expense (anchor = its date, first price = its
-- amount, its category and fund) and links the expense as the first,
-- checked payment. All or nothing. Returns the expense's id.
create function public.save_expense(
  p_name text,
  p_amount_pence bigint,
  p_date date,
  p_id uuid default null,
  p_category_id uuid default null,
  p_new_category_name text default null,
  p_new_category_kind text default null,
  p_fund_id uuid default null,
  p_account_label text default null,
  p_notes text default null,
  p_repeat text default null
)
returns uuid
language plpgsql
security invoker
set search_path = ''
as $$
declare
  uid uuid := (select auth.uid());
  v_name text := btrim(p_name);
  v_category_id uuid := p_category_id;
  v_rule_id uuid;
  v_id uuid;
begin
  if uid is null then
    raise exception 'save_expense: not signed in' using errcode = '42501';
  end if;

  if coalesce(char_length(v_name), 0) not between 1 and 100
     or p_amount_pence is null or p_amount_pence not between 1 and 1000000000
     or p_date is null
     or char_length(p_account_label) > 50
     or char_length(p_notes) > 500 then
    raise exception 'save_expense: a name (1-100), an amount of 1p to £10m and a date are needed' using errcode = '22023';
  end if;
  if (p_category_id is null) = (p_new_category_name is null) then
    raise exception 'save_expense: choose a category or name a new one' using errcode = '22023';
  end if;
  if p_new_category_name is not null and (
       char_length(btrim(p_new_category_name)) not between 1 and 50
       or p_new_category_kind is null or p_new_category_kind not in ('need', 'want')) then
    raise exception 'save_expense: a new category needs a name (1-50) and need or want' using errcode = '22023';
  end if;
  if p_repeat is not null and (
       p_repeat not in ('weekly', 'fortnightly', 'monthly', 'quarterly', 'annually') or p_id is not null) then
    raise exception 'save_expense: repeat is weekly, fortnightly, monthly, quarterly or annually, on a new expense'
      using errcode = '22023';
  end if;

  if p_new_category_name is not null then
    insert into public.categories (user_id, name, kind)
    values (uid, btrim(p_new_category_name), p_new_category_kind)
    returning id into v_category_id;
  end if;

  if p_id is not null then
    update public.transactions
    set name = v_name, amount_pence = p_amount_pence, date = p_date, category_id = v_category_id,
        fund_id = p_fund_id, account_label = p_account_label, notes = p_notes
    where id = p_id and user_id = uid
    returning id into v_id;
    if v_id is null then
      raise exception 'save_expense: no such expense' using errcode = 'P0002';
    end if;
    return v_id;
  end if;

  if p_repeat is not null then
    insert into public.recurring_rules (user_id, name, category_id, fund_id, frequency, anchor_date, generated_through)
    values (uid, left(v_name, 50), v_category_id, p_fund_id, p_repeat, p_date, p_date)
    returning id into v_rule_id;
    insert into public.recurring_prices (user_id, rule_id, effective_from, amount_pence)
    values (uid, v_rule_id, p_date, p_amount_pence);
  end if;

  insert into public.transactions
    (user_id, name, amount_pence, date, category_id, fund_id, account_label, notes, recurring_rule_id, unchecked)
  values (uid, v_name, p_amount_pence, p_date, v_category_id, p_fund_id, p_account_label, p_notes, v_rule_id, false)
  returning id into v_id;
  return v_id;
end;
$$;

revoke execute on function public.save_expense(text, bigint, date, uuid, uuid, text, text, uuid, text, text, text)
  from public, anon;
grant execute on function public.save_expense(text, bigint, date, uuid, uuid, text, text, uuid, text, text, text)
  to authenticated;

-- create_recurring_rule ------------------------------------------------------
-- A rule with its first price (effective from the anchor). p_link_ids (up to
-- 10 of the caller's expenses with no rule) become its past, checked
-- payments; then the rule counts as generated through the anchor, which must
-- be the latest of them. Returns the rule's id.
create function public.create_recurring_rule(
  p_name text,
  p_category_id uuid,
  p_frequency text,
  p_anchor_date date,
  p_amount_pence bigint,
  p_fund_id uuid default null,
  p_link_ids uuid[] default '{}'
)
returns uuid
language plpgsql
security invoker
set search_path = ''
as $$
declare
  uid uuid := (select auth.uid());
  v_links uuid[] := coalesce(p_link_ids, '{}');
  v_rule_id uuid;
  v_linked int;
begin
  if uid is null then
    raise exception 'create_recurring_rule: not signed in' using errcode = '42501';
  end if;
  if coalesce(char_length(btrim(p_name)), 0) not between 1 and 50
     or p_category_id is null or p_anchor_date is null
     or p_frequency is null or p_frequency not in ('weekly', 'fortnightly', 'monthly', 'quarterly', 'annually')
     or p_amount_pence is null or p_amount_pence not between 1 and 1000000000
     or cardinality(v_links) > 10
     or cardinality(v_links) <> (select count(distinct l) from unnest(v_links) as l) then
    raise exception 'create_recurring_rule: a name, category, frequency, anchor and amount are needed' using errcode = '22023';
  end if;

  insert into public.recurring_rules (user_id, name, category_id, fund_id, frequency, anchor_date)
  values (uid, btrim(p_name), p_category_id, p_fund_id, p_frequency, p_anchor_date)
  returning id into v_rule_id;
  insert into public.recurring_prices (user_id, rule_id, effective_from, amount_pence)
  values (uid, v_rule_id, p_anchor_date, p_amount_pence);

  if cardinality(v_links) > 0 then
    if exists (select 1 from public.transactions
               where user_id = uid and id = any (v_links) and date > p_anchor_date) then
      raise exception 'create_recurring_rule: the anchor must be the latest linked payment' using errcode = '22023';
    end if;
    update public.transactions
    set recurring_rule_id = v_rule_id, unchecked = false
    where user_id = uid and id = any (v_links) and recurring_rule_id is null;
    get diagnostics v_linked = row_count;
    if v_linked <> cardinality(v_links) then
      raise exception 'create_recurring_rule: a payment is gone or already recurring' using errcode = 'PT409';
    end if;
    update public.recurring_rules set generated_through = p_anchor_date where id = v_rule_id;
  end if;
  return v_rule_id;
end;
$$;

revoke execute on function public.create_recurring_rule(text, uuid, text, date, bigint, uuid, uuid[]) from public, anon;
grant execute on function public.create_recurring_rule(text, uuid, text, date, bigint, uuid, uuid[]) to authenticated;

-- apply_recurring_price ------------------------------------------------------
-- Sets the rule's price from p_from (replacing one from the same day) and
-- writes the amounts the caller worked out with calc's amountOn for the
-- payments it moves: p_updates = [{"id": uuid, "amount_pence": int}], each a
-- payment of this rule dated on or after p_from. Earlier payments never
-- change. All or nothing; PT409 if a listed payment isn't there any more.
create function public.apply_recurring_price(
  p_rule_id uuid,
  p_from date,
  p_amount_pence bigint,
  p_updates jsonb
)
returns void
language plpgsql
security invoker
set search_path = ''
as $$
declare
  uid uuid := (select auth.uid());
  v_count int;
  v_updated int;
begin
  if uid is null then
    raise exception 'apply_recurring_price: not signed in' using errcode = '42501';
  end if;
  if p_from is null or p_amount_pence is null or p_amount_pence not between 1 and 1000000000
     or coalesce(jsonb_typeof(p_updates), '') <> 'array' or jsonb_array_length(p_updates) > 1000
     or exists (select 1 from jsonb_array_elements(p_updates) as e (value)
                where jsonb_typeof(e.value) <> 'object'
                   or jsonb_typeof(e.value -> 'id') <> 'string'
                   or not private.is_whole_pence(e.value -> 'amount_pence', 1)) then
    raise exception 'apply_recurring_price: a date, an amount of 1p to £10m and the payments to change are needed'
      using errcode = '22023';
  end if;

  perform 1 from public.recurring_rules where id = p_rule_id and user_id = uid for update;
  if not found then
    raise exception 'apply_recurring_price: no such recurring payment' using errcode = 'P0002';
  end if;

  insert into public.recurring_prices (user_id, rule_id, effective_from, amount_pence)
  values (uid, p_rule_id, p_from, p_amount_pence)
  on conflict (user_id, rule_id, effective_from) do update set amount_pence = excluded.amount_pence;

  v_count := jsonb_array_length(p_updates);
  update public.transactions t
  set amount_pence = u.amount_pence
  from jsonb_to_recordset(p_updates) as u (id uuid, amount_pence bigint)
  where t.id = u.id and t.user_id = uid and t.recurring_rule_id = p_rule_id and t.date >= p_from;
  get diagnostics v_updated = row_count;
  if v_updated <> v_count then
    raise exception 'apply_recurring_price: a payment changed meanwhile' using errcode = 'PT409';
  end if;
end;
$$;

revoke execute on function public.apply_recurring_price(uuid, date, bigint, jsonb) from public, anon;
grant execute on function public.apply_recurring_price(uuid, date, bigint, jsonb) to authenticated;

-- hourly job -----------------------------------------------------------------
-- pg_cron runs private.request_recurring_run() every hour. It POSTs to
-- <app_url>/api/cron/recurring with `Authorization: Bearer <cron_secret>`,
-- both read from Supabase Vault (secrets named app_url and cron_secret; see
-- the README). With either missing it does nothing and returns null, so a
-- local or preview database never calls out. The route then generates due
-- payments for every user in their own time zone.
--
-- It runs as the job's owner (postgres), which can read the Vault; nobody
-- else may call it.
create function private.request_recurring_run()
returns bigint
language plpgsql
security invoker
set search_path = ''
as $$
declare
  v_url text;
  v_secret text;
begin
  select decrypted_secret into v_url from vault.decrypted_secrets where name = 'app_url';
  select decrypted_secret into v_secret from vault.decrypted_secrets where name = 'cron_secret';
  if coalesce(btrim(v_url), '') = '' or coalesce(btrim(v_secret), '') = '' then
    return null;
  end if;
  return net.http_post(
    url := rtrim(btrim(v_url), '/') || '/api/cron/recurring',
    headers := jsonb_build_object('Authorization', 'Bearer ' || v_secret, 'Content-Type', 'application/json'),
    body := '{}'::jsonb,
    timeout_milliseconds := 30000
  );
end;
$$;

revoke execute on function private.request_recurring_run() from public, anon, authenticated;

-- pg_cron and pg_net are on Supabase (hosted and the local image). Where a
-- database lacks them the migration still applies, without the job.
do $$
begin
  if exists (select 1 from pg_available_extensions where name = 'pg_cron')
     and exists (select 1 from pg_available_extensions where name = 'pg_net') then
    create extension if not exists pg_cron;
    create extension if not exists pg_net with schema extensions;
    perform cron.schedule('recurring-payments', '0 * * * *', 'select private.request_recurring_run()');
  else
    raise notice 'pg_cron or pg_net is not available: the hourly recurring-payments job was not scheduled';
  end if;
end;
$$;
